INSERT INTO jobs (id, company_id, title, position, level, type, quantity, city, address, work_mode, salary_min, salary_max, description, requirements, benefits, deadline, status, rejected_reason, created_by, created_at, updated_at) VALUES
    ('d0000000-0000-4000-8000-000000000001', '11111111-1111-4111-8111-111111111111', 'Java Backend Developer (FRESHER) #1', 'Java Backend Developer', 'FRESHER', 'FULLTIME', 2, 'Hà Nội', 'Cầu Giấy, Hà Nội', 'ONSITE', 12000000, 18000000, 'Cơ hội gia nhập Công ty Cổ phần Rikkeisoft ở vị trí Java Backend Developer (FRESHER) #1. Tham gia phát triển các hệ thống quy mô lớn, môi trường Agile chuyên nghiệp, hỗ trợ đào tạo và thưởng dự án hấp dẫn.', 'Thành thạo JAVA_CORE, SPRING_BOOT, SQL. Cấp độ mong muốn: FRESHER. Tư duy giải quyết vấn đề tốt và chủ động trong công việc.', 'Lương thưởng cạnh tranh theo năng lực, đóng BHXH đầy đủ, hỗ trợ thiết bị làm việc và đào tạo nâng cao.', ((NOW() + interval '30 days')::date), 'APPROVED', NULL, '5326dd94-3eef-481a-ab1c-1067d9697875', NOW() - interval '30 days', NOW()),
    ('d0000000-0000-4000-8000-000000000002', '22222222-2222-4222-8222-222222222222', 'Frontend React Developer (JUNIOR) #2', 'Frontend React Developer', 'JUNIOR', 'FULLTIME', 2, 'Hà Nội', 'Nam Từ Liêm, Hà Nội', 'ONSITE', 18000000, 26000000, 'Cơ hội gia nhập Rikkei Digital Solutions ở vị trí Frontend React Developer (JUNIOR) #2. Tham gia phát triển các hệ thống quy mô lớn, môi trường Agile chuyên nghiệp, hỗ trợ đào tạo và thưởng dự án hấp dẫn.', 'Thành thạo REACT, TYPESCRIPT, JAVASCRIPT. Cấp độ mong muốn: JUNIOR. Tư duy giải quyết vấn đề tốt và chủ động trong công việc.', 'Lương thưởng cạnh tranh theo năng lực, đóng BHXH đầy đủ, hỗ trợ thiết bị làm việc và đào tạo nâng cao.', ((NOW() + interval '30 days')::date), 'APPROVED', NULL, 'f4c530f6-3b46-4e5d-b4db-ce699cd3db25', NOW() - interval '29 days', NOW()),
